    private List<JSONObject> filtered(){List<JSONObject> result=new ArrayList<>();String q=query.toLowerCase(Locale.ROOT).trim();for(JSONObject j:rows)if(q.isEmpty()||j.toString().toLowerCase(Locale.ROOT).contains(q))result.add(j);return result;}
