    static String equipmentType(String kind){return kind.equals("lens")?"镜头":kind.equals("flash")?"闪光灯":kind.equals("filter")?"滤镜":"相机";}
    void equipment(){a.worker.execute(()->{List<JSONObject> records=studio.repository.list("equipment",null);a.main.post(()->a.openUtility(new UtilitySheet(a,"器材档案",s->{LinearLayout add=a.row();String[] names={"相机","镜头","闪灯","滤镜"},types={"camera","lens","flash","filter"};for(int i=0;i<4;i++){int n=i;StudioUi.append(add,a,a.button("＋"+names[i],()->{s.dismiss();editEquipment(RollRepository.object("kind",types[n]));}));}a.add(s.content,add,-1,48);for(JSONObject j:records)s.action(j.optString("name")+" · "+equipmentType(j.optString("kind")),()->{s.dismiss();editEquipment(j);});s.note("通用模板与自定义器材资料，不代表手机会调用这些品牌相机或控制外接闪灯。");s.action("通用 135 相机模板",()->{s.dismiss();editEquipment(RollRepository.object("kind","camera","name","135 胶片相机","width",36,"height",24));});s.action("通用标准镜头模板",()->{s.dismiss();editEquipment(RollRepository.object("kind","lens","name","50mm 标准镜头","focal",50,"max_aperture",1.8));});})));});}
    private void editEquipment(JSONObject record){JSONObject j=RollRepository.copy(record);String type=j.optString("kind","camera");a.openUtility(new UtilitySheet(a,"器材 · "+equipmentType(type),s->{EditText name=StudioUi.field(a,s,"名称",j.optString("name","自定义器材"),false);Map<String,EditText> fields=new LinkedHashMap<>();String[][] defs=type.equals("camera")?new String[][]{{"width","有效宽 mm","36"},{"height","有效高 mm","24"}}:type.equals("lens")?new String[][]{{"focal","实际焦距 mm","50"},{"max_aperture","最大光圈","1.8"},{"min_aperture","最小光圈","22"}}:type.equals("flash")?new String[][]{{"gn","GN，ISO100 / 米","36"},{"zoom","GN 对应灯头焦距 mm","35"}}:new String[][]{{"nd","曝光补偿档数","3"},{"temperature","屏幕色温倾向 -1 至 1","0"}};for(String[] def:defs)fields.put(def[0],StudioUi.field(a,s,def[1],j.optString(def[0],def[2]),true));EditText notes=StudioUi.field(a,s,"备注 / 型号资料来源",j.optString("notes"),false);s.action("保存",()->{try{j.put("name",StudioUi.required(name));j.put("notes",notes.getText().toString());if(!j.has("id"))j.put("id",UUID.randomUUID().toString());for(String key:fields.keySet())j.put(key,StudioUi.number(fields.get(key),key.equals("temperature")?-1:0,key.equals("temperature")?1:10000));s.dismiss();StudioUi.work(a,()->studio.repository.saveProfile("equipment",j),this::equipment);}catch(Exception e){a.toast(e.getMessage());}});if(j.has("id"))s.action("删除器材资料",()->new AlertDialog.Builder(a,ThemeUi.alertTheme()).setTitle("删除器材资料？").setMessage("已有照片和测光快照保留。").setNegativeButton("取消",null).setPositiveButton("删除",(d,w)->{s.dismiss();StudioUi.work(a,()->studio.repository.deleteProfile("equipment",j.optString("id")),this::equipment);}).show());}));}
    void pickMeterEquipment(){a.worker.execute(()->{List<JSONObject> profiles=studio.repository.list("equipment",null);a.main.post(()->a.openUtility(new UtilitySheet(a,"套用测光器材",s->{for(JSONObject j:profiles)s.action(j.optString("name"),()->{String type=j.optString("kind");if(type.equals("lens")){studio.meter.focal=j.optDouble("focal",50);studio.meter.aperture=j.optDouble("max_aperture",8);}if(type.equals("flash"))studio.meter.gn=j.optDouble("gn",36);if(type.equals("filter"))studio.meter.nd=j.optDouble("nd",0);if(type.equals("camera")){double w=j.optDouble("width",36),h=j.optDouble("height",24);studio.meter.coc=Math.hypot(w,h)/1500;}s.dismiss();studio.meter.refresh();studio.meter.advanced();});})));});}
