    private void filmProfileRow(UtilitySheet sheet,JSONObject j){LinearLayout card=a.row();card.setPadding(a.dp(12),a.dp(10),a.dp(12),a.dp(10));card.setBackground(a.bg(PANEL,16,tone(AppTheme.BORDER)));ImageView cover=new ImageView(a);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.setImageDrawable(new LabelCover(j));a.add(card,cover,116,76);if(!j.optString("cover").isEmpty())thumb(cover,new File(new File(a.getFilesDir(),"covers"),new File(j.optString("cover")).getName()),j.optString("id",j.optString("name")));LinearLayout labels=a.column();labels.setPadding(a.dp(12),0,0,0);TextView name=a.text(j.optString("name"),15,CREAM);name.setMaxLines(2);name.setEllipsize(TextUtils.TruncateAt.END);a.add(labels,name,-1,-2);TextView type=a.text(j.optString("type","彩色")+" · ISO "+j.optInt("nominal_iso",400),12,MUTED);type.setMaxLines(2);a.add(labels,type,-1,-2);card.addView(labels,new LinearLayout.LayoutParams(0,-2,1));card.setContentDescription(j.optString("name")+"，"+j.optString("type")+"，ISO "+j.optInt("nominal_iso",400));card.setFocusable(true);card.setOnClickListener(v->{sheet.dismiss();filmProfileActions(j);});a.add(sheet.content,card,-1,Math.max(104,Math.round(60+36*a.getResources().getConfiguration().fontScale)));a.gap(sheet.content,10);}
    JSONObject filmData(int stock){String name=FilmCatalog.NAMES[FilmCatalog.safe(stock)];int nominal=400;java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?<!\\d)(\\d{2,4})(?!\\d)").matcher(name);if(m.find())try{nominal=Integer.parseInt(m.group(1));}catch(Exception ignored){}return RollRepository.object("name",name,"stock",stock,"nominal_iso",nominal,"type",name.contains("黑白")||name.contains("硬黑")||name.contains("HP5")||name.contains("棕片")?"黑白":name.contains("反转")||name.contains("正片")||name.contains("Kodachrome")?"反转片":"彩色","temperature",0);}
    void filmDetails(int stock){filmProfileActions(filmData(stock));}
    private void filmProfileActions(JSONObject j){a.openUtility(new UtilitySheet(a,j.optString("name"),s->{ImageView cover=new ImageView(a);cover.setScaleType(ImageView.ScaleType.FIT_CENTER);cover.setImageDrawable(new LabelCover(j));a.add(s.content,cover,-1,168);if(!j.optString("cover").isEmpty())thumb(cover,new File(new File(a.getFilesDir(),"covers"),new File(j.optString("cover")).getName()),j.optString("id",j.optString("name")));s.note(j.optString("type","彩色")+" · ISO "+j.optInt("nominal_iso",400)+"\n标称感光度供档案和测光使用，不设置手机传感器 ISO；风格模拟不等于实体胶片的精确光谱响应。");s.action("用于手机当前风格",()->{studio.leaveMeter();a.setStock(j.optInt("stock",0));a.settings.temperature=(float)j.optDouble("temperature",0);a.syncFilm();s.dismiss();});s.action("用于实体测光感光度",()->{studio.meter.nominal=j.optDouble("nominal_iso",400);studio.meter.refresh();s.dismiss();});s.action("编辑 / 另存自定义资料",()->{s.dismiss();editFilm(j);});if(j.has("id"))s.action("更换封面",()->{s.dismiss();studio.media.pickCover("film_profiles",j);});}));}
    private void editFilm(JSONObject old){JSONObject j=old==null?RollRepository.object("stock",a.settings.stock):RollRepository.copy(old);a.openUtility(new UtilitySheet(a,"胶片资料",s->{EditText name=StudioUi.field(a,s,"名称",j.optString("name","自定义胶片"),false),iso=StudioUi.field(a,s,"标称 ISO",j.optString("nominal_iso","400"),true);String[] types={"彩色","黑白","反转片"};s.options(types,Arrays.asList(types).indexOf(j.optString("type","彩色")),n->{try{j.put("type",types[n]);}catch(JSONException ignored){}});s.options(new String[]{"日光倾向","中性","钨丝灯倾向"},j.optDouble("temperature",0)>0?0:j.optDouble("temperature",0)<0?2:1,n->{try{j.put("temperature",n==0?.5:n==2?-.5:0);}catch(JSONException ignored){}});s.action("选择关联风格",()->new AlertDialog.Builder(a,ThemeUi.alertTheme()).setTitle("风格").setItems(FilmCatalog.NAMES,(d,w)->{try{j.put("stock",w);}catch(JSONException ignored){}}).show());s.action("保存资料",()->{try{j.put("name",StudioUi.required(name));j.put("nominal_iso",StudioUi.number(iso,6,204800));if(!j.has("id"))j.put("id",UUID.randomUUID().toString());s.dismiss();StudioUi.work(a,()->studio.repository.saveProfile("film_profiles",j),this::filmProfiles);}catch(Exception e){a.toast(e.getMessage());}});}));}
    void annotate(String id){a.worker.execute(()->{JSONObject item=studio.repository.find("items",id);if(item==null)item=a.readMeta(id);final JSONObject record=item;a.main.post(()->a.openUtility(new UtilitySheet(a,"档案与补填",s->{JSONObject previous=record.optJSONObject("annotations");if(previous==null)previous=new JSONObject();s.note("原始 EXIF 与手机实际参数保留；下方内容是独立补填记录，不回写原片。");EditText camera=StudioUi.field(a,s,"相机",previous.optString("camera"),false),lens=StudioUi.field(a,s,"镜头",previous.optString("lens"),false),iso=StudioUi.field(a,s,"ISO / EI，可留空",previous.optString("iso"),true),f=StudioUi.field(a,s,"光圈，可留空",previous.optString("aperture"),true),t=StudioUi.field(a,s,"快门秒，可留空",previous.optString("seconds"),true),date=StudioUi.field(a,s,"拍摄日期 yyyy:MM:dd HH:mm:ss，可留空",previous.optString("date"),false),notes=StudioUi.field(a,s,"备注",previous.optString("notes"),false);s.action("保存补填",()->{try{JSONObject data=RollRepository.object("camera",camera.getText().toString(),"lens",lens.getText().toString(),"notes",notes.getText().toString());for(EditText e:new EditText[]{iso,f,t})if(e.length()>0)StudioUi.number(e,.000001,1000000);if(iso.length()>0)data.put("iso",iso.getText().toString());if(f.length()>0)data.put("aperture",f.getText().toString());if(t.length()>0)data.put("seconds",t.getText().toString());if(date.length()>0){if(!PrintMetadata.validDate(date.getText().toString()))throw new IllegalArgumentException("拍摄日期格式无效");data.put("date",date.getText().toString());}s.dismiss();StudioUi.work(a,()->studio.repository.annotate(id,data),()->{a.toast("补填已保存");if(a.page==2)render();});}catch(Exception e){a.toast(e.getMessage());}});s.action("移动到其他胶卷",()->{s.dismiss();chooseRoll(false,r->StudioUi.work(a,()->studio.repository.move(Collections.singletonList(id),r.optString("id")),()->{if(a.page==2)render();}));});if(NegativeStore.valid(id))s.action("原件导出",()->{s.dismiss();studio.media.originals(Collections.singletonList(id));});})));});}
    private void meterDetail(JSONObject j){a.openUtility(new UtilitySheet(a,"测光记录",s->{s.note(String.format(Locale.US,"EV100 %.2f\n建议 f/%.1f · %s · EI %.0f\nND %.1f 档 · 补偿 %+.1f 档\n倒易率 %s\n\n原始手机元数据仅作为测光来源，以上为实体摄影建议。",j.optDouble("ev100"),j.optDouble("aperture"),MeterMath.time(j.optDouble("seconds")),j.optDouble("ei"),j.optDouble("nd"),j.optDouble("compensation"),j.optString("reciprocity")));if(!j.optString("reference").isEmpty()){ImageView im=new ImageView(a);im.setScaleType(ImageView.ScaleType.FIT_CENTER);a.add(s.content,im,-1,220);thumb(im,new File(new File(a.getFilesDir(),"meter-references"),new File(j.optString("reference")).getName()),j.optString("id"));}s.action("备注与补填",()->{s.dismiss();annotate(j.optString("id"));});s.action("导出所属胶卷 CSV",()->{s.dismiss();studio.media.csv(j.optString("roll_id"));});}));}
    void meterTrash(){a.worker.execute(()->{List<JSONObject> records=studio.repository.meterTrash();a.main.post(()->a.openUtility(new UtilitySheet(a,"测光记录回收站 · 7天",s->{if(records.isEmpty())s.note("回收站为空");for(JSONObject j:records)s.action("恢复 · "+j.optString("id"),()->{s.dismiss();StudioUi.work(a,()->studio.repository.restoreMeter(j.optString("id")),this::meterTrash);});})));});}
    static final class LabelCover extends FilmLabelDrawable{LabelCover(JSONObject value){super(value.optInt("stock",1),coverName(value),value.optInt("nominal_iso",400));}static String coverName(JSONObject j){int id=FilmCatalog.safe(j.optInt("stock",1));String name=j.optString("name",FilmCatalog.NAMES[id]);return j.has("kind")||name.equals(FilmCatalog.NAMES[id])?FilmLabelStyle.of(id).mark():name;}}
